public class College
{
  private int myTuition;
  public College(int tuition)
  {
    myTuition = tuition;
  }
  public int getTuition()
  {
    return myTuition;
  }
  public double getCost()
  {
    return getTuition();
  }
}
public class Graduate extends College
{
  private int myYears;
  public Graduate()
  {
    super(15000);
    myYears = 2;
  }
  public Graduate(int tuition)
  {
    super(tuition);
    myYears = 2;
  }
  public Graduate(int tuition, int years)
  {
    super(tuition);
    myYears = years;
  }
  public int getNumYears()
  {
    return myYears;
  }
  public double getCost()
  {
    if (getNumYears() > 2)
      return 500. + super.getCost()/2;
    return 300. + super.getCost();
  }
}
public class OnLine extends College
{
  private int myRating;
  public OnLine(int tuition)
  {
    super(tuition);
    myRating = 0;
  }
  public OnLine(int tuition, int rating)
  {
    super(tuition);
    myRating = rating;
  }
  public int getRating()
  {
    return myRating;
  }
  public double getCost()
  {
    int rate = getRating();
    if (rate <= 1)
      return super.getCost();
    if (rate <= 5)
      return super.getCost() + rate * 10;
    if (rate <= 7)
      return super.getCost() + rate * 25;
    return super.getCost() + rate * 100;
  }
}
