turn this to expectiminimax. def minimax(state, depth, a, b, is_maximizer):
    if depth == 0:
        return evaluate_state(state), state

    if is_maximizer:
        best_score = float('-inf')
        best_state = None
        for child_state in get_possible_moves(state, depth):
            score, _ = minimax(child_state, depth - 1, a, b, False)
            if score > best_score:
                best_score = score
                best_state = child_state
            if best_score > b:
                break
            a = max(a, best_score)
        return best_score, best_state
    else:
        best_score = float('inf')
        best_state = None
        for child_state in get_possible_moves(state, depth):
            if depth % 3 == 0:
                score, _ = minimax(child_state, depth - 1, a, b, True)
            else:
                score, _ = minimax(child_state, depth - 1, a, b, False)
            if score < best_score:
                best_score = score
                best_state = child_state
            if best_score < a:
                break
            b = min(b, best_score)
        return best_score, best_state

