                    isComfirmEmail: false,
                    emailNotice: false
                }));
        } else if (args.length === 2 && args[0] === "try_create_battle_ctf") {
            if (tank.rank > 3) {
                try {
                    const data = JSON.parse(args[1]);
                    const battle = new CTFBattle(false, data.gameName, data.mapId, data.time, data.numPlayers, data.minRang, data.maxRang, data.numFlags, !data.inventory, data.autoBalance, data.frielndyFire, data.pay, false);
                    this.battles.push(battle);
                    this.broadcast("create_battle;" + JSON.stringify(battle.toObject()));
                    console.log('\x1b[35m%s\x1b[0m', ' > ' + tank.name + " создал битву " + data.gameName);
                } catch (e) {
                    console.log(e);
                }
            } else {
                this.send(socket, "server_message;Создавать битвы можно со звания Капрал")
            }
        } else if (args.length === 2 && args[0] === "try_create_battle_dom") {
            if (tank.rank > 3) {
                try {
                    const data = JSON.parse(args[1]);
                    const battle = new DOMBattle(false, data.gameName, data.mapId, data.time, data.numPlayers, data.minRang, data.maxRang, data.numPointsScore, !data.inventory, data.autoBalance, data.frielndyFire, data.pay, false);
                    this.battles.push(battle);
                    this.broadcast("create_battle;" + JSON.stringify(battle.toObject()));
                    console.log('\x1b[35m%s\x1b[0m', ' > ' + tank.name + " создал битву " + data.gameName);
                } catch (e) {
                    console.log(e);
                }
            } else {
                this.send(socket, "server_message;Создавать битвы можно со звания Капрал")
            }
        } else if (args.length === 2 && args[0] === "try_create_battle_tdm") {
            if (tank.rank > 3) {
                try {
                    const data = JSON.parse(args[1]);
                    console.log('data', data);
                    const battle = new TDMBattle(false, data.gameName, data.mapId, data.time, data.numPlayers, data.minRang, data.maxRang, data.numKills, !data.inventory, data.autoBalance, data.frielndyFire, data.pay);
                    this.battles.push(battle);
                    this.broadcast("create_battle;" + JSON.stringify(battle.toObject()));
                    console.log('\x1b[35m%s\x1b[0m', ' > ' + tank.name + " создал битву " + data.gameName);
                } catch (e) {
                    console.log(e);
                }
            } else {
                this.send(socket, "server_message;Создавать битвы можно со звания Капрал")
            }
        } else if (args[0] === "try_create_battle_dm") {
            if (tank.rank > 3) {
                try {
                    const withoutBonuses = args[10] === 'true';
                    const withoutSupplies = args[9] === 'true';

                    var battle = new DMBattle(false, args[1], args[2], args[3], args[5], args[6], args[7], args[4], !withoutBonuses, withoutSupplies);
                    this.battles.push(battle);
                    this.broadcast("create_battle;" + JSON.stringify(battle.toObject()));
                    console.log('\x1b[35m%s\x1b[0m', ' > ' + tank.name + " создал битву в режиме DM ");
                } catch (e) {
                    console.log(e);
                }

            } else {
                this.send(socket, "server_message;Создавать битвы можно со звания Капрал")
            }
        } else if (args.length === 2 && args[0] === "get_show_battle_info") {
            for (var i in battles) {
                if (battles[i].battleId === args[1]) {
                    this.send(socket, "show_battle_info;" + JSON.stringify(battles[i].toDetailedObject(tank)));
                }

            }

        } else if (args.length === 2 && (args[0] === "enter_battle_spectator")) {
            var battle = this.findBattle(args[1]);

            if (battle !== null)
                battle.addSpectator(tank);
        } else if (args[3] !== "null" && args.length === 3 && (args[0] === "enter_battle_team")) {

            var battle = this.findBattle(args[1]);

            if (battle !== null) {
                this.anticheat++;
                setTimeout(() => {
                    if (this.anticheat > 1) {
                        this.send(tank.socket, "battle;kick_by_cheats");
                        tank.socket.destroy();
                    }
                }, 50);
                setTimeout(() => {
                    this.anticheat--;
                }, 1000);
                var type = args[2] === "false" ? "BLUE" : "RED";
                send(socket, "lobby;start_battle");
                var user = battle.addPlayer(tank, type);

                if (user !== null)
                    this.broadcast("add_player_to_battle;" + JSON.stringify(
                        {
                            kills: user.kills,
                            battleId: args[2],
                            name: tank.name,
                            rank: tank.rank,
                            id: tank.name,
                            type: type
                        }));

            }
        } else if (args[3] !== "null" && args.length === 3 && (args[0] === "enter_battle")) {
            var battle = this.findBattle(args[1]);
            send(socket, "lobby;start_battle");

            if (battle !== null && battle.getTeamCount() === 1) {
                var user = battle.addPlayer(tank);
                if (user !== null)
                    this.broadcast("add_player_to_battle;" + JSON.stringify(
                        {
                            kills: user.kills,
                            battleId: args[2],
                            name: tank.name,
                            rank: tank.rank,
                            id: tank.name,
                            type: "NONE"
                        }));
            }
        } else if (args.length === 2 && args[0] === "check_battleName_for_forbidden_words") {
            send(socket, "lobby;check_battle_name;" + args[1]);
        }         else if (args.length === 1 && args[0] === "get_garage_data") {
            var tank = socket.tank;
            if (tank !== null) {
                setTimeout(() => {
                    tank.garage.initiate(socket);
                    this.initEffectModel(socket);

                    if (this.hasPlayer(tank.name))
                        this.removePlayer(tank.name);
                }, 1000);
            }
        }
    }

}

