 function authenticate(socket, username, data = null)
 {

	 if (!isset(players[socket.id]) && search(username, players) === null)
	 {


			 var callback = (data) =>
			 {
				 if (Object.keys(data) === 0)
				 {
					 send(socket, "auth;denied");
					 return false;
				 }
				 var tank = Tank.fromJSON(data);
				 if (!tank.block)
				 {
					 send(socket, "auth;accept");

					 online(socket, tank);
					 tank.ip = socket.remoteAddress;
					 tank.sendPanel();
					 tank.sendProgress();
					 lobby.initEffectModel(socket);

					 var send_garage = false;
					 var send_lobby = true;
					 battle = tank.findBattle();

					 if (battle !== null)
					 {
						 var user = battle.getUser(tank.name);
						 //user.dirty = false;
						 if (user !== null)
						 {
							 send(socket, "lobby;init_battlecontroller");
							 setTimeout(() =>
							 {
								 battle.initiate(socket);
								 battle.rejoin(tank);
							 }, 2000);
							 send_garage = false;
							 send_lobby = false;
						 }
					 }
				 }
				 else
				 {
					 send(socket, "auth;ban;Аккаунт был заблокирован за нарушение правил игры. \nЕсли вы уверены, что мы ошиблись - пишите на <PRESIDIO_ANONYMIZED_EMAIL_ADDRESS>");
				 }
				 if (send_garage)
				 {
					 tank.garage.initiate(socket);
					 lobby.chat.initiate(tank);
					 tank.battleId = null;
				 }
				 else if (send_lobby)
				 {
					 lobby.chat.initiate(tank);
					 lobby.getBattles(socket, tank);
				 }
				 //tank.battleId = null;
			 };
			 if (data === null)
				 playerJson(username, callback);
			 else
				 callback(data);

	 }
	 else
		 socket.destroy();

	 return true;
