const WeaponModel = require("./WeaponModel"),
	{
		getMaxDamage,
		getDamage
	} = require("./server");

class ShaftModel extends WeaponModel
{

	onData(socket, args)
	{
		if (this.battle === null || this.user === null) return;
		try {
			if (args[0] === "quick_shot_shaft" || args[0] === "fire") {
				const data = JSON.parse(args[1]);


				let damage = 0;

				if (args[0] === "quick_shot_shaft") {
					damage = getDamage(this.name, this.modification);
					this.battle.broadcast("shaft_quick_shot;" + this.user.nickname + ";" + args[1]);
				}

				if (args[0] === "fire") {
					damage = getMaxDamage(this.name, this.modification) / 100 * (100 - data.energy / 10);
					this.battle.broadcast("fire;" + this.user.nickname + ";" + args[1]);
				}


				if (data.targets.length === 0) return;

				const target = data.targets[0];
				const killer = this.user;
				const user = this.battle.getUser(target.target_id || target.target.id);

				if (user) user.attack(killer, damage, socket.tank.garage.mounted_turret, user.team_type.toUpperCase(), this.battle.getFriendlyFire());
			}

		} catch (e) {
		}
	}
}

