using Godot;
using System;

public partial class Player : CharacterBody3D
{
	public const uint MaxLifepoints = 200;

	[Export]
	public float Speed { get; private set; } = 5.0f;

	[Export]
	public float JumpVelocity { get; private set; } = 4.5f;

