		{
			velocity.X = Mathf.Lerp(Velocity.X, 0, Speed * (float)delta);
			velocity.Z = Mathf.Lerp(Velocity.Z, 0, Speed * (float)delta);
		}

		Velocity = velocity;
		MoveAndSlide();

		velocity.Y = 0;
		_animationTree.Set("parameters/walking/blend_amount", velocity.LimitLength(1).Length());
		if (Mathf.IsZeroApprox(velocity.Length())) return;

		_visual.LookAt(Position + 10 * velocity, Vector3.Up, true);
		//var angle = 0;
		//var transform = _visual.Transform;
		//transform.Basis = new(Vector3.Up, angle);
		//_visual.Transform = transform;
	}
	private Vector2 GetInputDirectionWithAngles()
	{
		Vector2 inputDirection = Vector2.Zero;

		// Gather the axis inputs
		float horizontal = Input.GetActionStrength("right") - Input.GetActionStrength("left");
		float vertical = Input.GetActionStrength("up") - Input.GetActionStrength("down");

		if (vertical > 0) 
		{
			// Moving up
			inputDirection.Y += Mathf.Sin(UpwardAngleDeg * (Mathf.Pi / 180.0f)) * vertical;
			inputDirection.X += Mathf.Cos(UpwardAngleDeg * (Mathf.Pi / 180.0f)) * horizontal;
		}
		else if (vertical < 0)
		{
			// Moving down
			inputDirection.Y += Mathf.Sin(DownwardAngleDeg * (Mathf.Pi / 180.0f)) * vertical;
			inputDirection.X += Mathf.Cos(DownwardAngleDeg * (Mathf.Pi / 180.0f)) * horizontal;
		}
		else
		{
			// Just walking horizontally or standing still
			inputDirection.X = horizontal;
			inputDirection.Y = vertical;
		}

		return inputDirection.Normalized();
	}

	public void OnAttackTimeOut()
	{
		_attackTimer.Start();

		var nearestEnemy = _gameManager.GetNearestEnemy();
		if (nearestEnemy == null) return;

		//nearestEnemy.TakeDamages();
	}

	public void TakeDamages(uint damages)
	{
		_lifepoints -= Math.Clamp(damages, 0, _lifepoints);
	}

	internal void Heal(uint damages)
	{
		_lifepoints = Math.Clamp(_lifepoints + damages, 0, MaxLifepoints);
	}
}

