         for(int i = 0; i < (int)RandomUtils.getRandom(1.0F, 6.0F); ++i) {
            this.spawnBonus(BonusType.CRYSTALL);
         }

         this.crystallFund = 0;
      }

      this.prevFund = (int)this.battlefieldModel.tanksKillModel.getBattleFund();
   }

